def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive = []
    for opp in opponents_status.values():
        if opp.get('alive'):
            alive.append(opp)

    if not alive:
        return max(0, min(budget, 18.0))

    prev_bids = []
    stressed_opponents = 0
    for opp in alive:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            prev_bids.append(prev['bid'])
        if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
            stressed_opponents += 1

    player_count = 1 + len(alive)
    approx_units = supply / float(WATER_REQ)
    scarcity = approx_units < player_count

    if hp <= 2 or no_water >= 2:
        base = DAILY_SALARY * 0.96
    elif hp <= 4 or no_water >= 1:
        base = DAILY_SALARY * 0.82
    elif scarcity:
        base = DAILY_SALARY * 0.62
    else:
        base = DAILY_SALARY * 0.38

    if prev_bids:
        highest_prev = max(prev_bids)
        avg_prev = sum(prev_bids) / float(len(prev_bids))
        if hp <= 4 or no_water >= 1:
            target = max(base, highest_prev + 2.0)
        else:
            target = max(base, avg_prev + 1.0)
            if highest_prev >= DAILY_SALARY * 0.9 and hp > 4 and no_water == 0:
                target = min(target, DAILY_SALARY * 0.45)
    else:
        target = base

    if stressed_opponents >= max(1, len(alive) // 2):
        target += 3.0

    if supply >= 22:
        target -= 4.0
    elif supply <= 17:
        target += 4.0

    target = max(0.0, min(float(budget), float(target)))
    return target

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context.get('supply', 0.0)
    day = day_context.get('day', 0)

    # Collect alive opponents and their yesterday bids
    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append((opp_id, opp))

    if not alive_opps:
        return min(my_status.get('budget', 0), DAILY_SALARY * 0.4)

    yesterday_bids = []
    for _, opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        bid = prev.get('bid', None)
        if bid is not None:
            try:
                yesterday_bids.append(float(bid))
            except Exception:
                pass

    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0

    my_hp = my_status.get('hp', 0)
    my_budget = my_status.get('budget', 0)
    no_water_days = my_status.get('no_water_days', 0)

    # Determine how aggressive to be
    # If opponents were bidding very high yesterday, match enough to avoid losing again.
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        if my_hp <= 2 or no_water_days >= 2:
            target = DAILY_SALARY * 0.95
        else:
            target = DAILY_SALARY * 0.35
    elif highest_prev_bid >= DAILY_SALARY * 0.55:
        # Moderate pressure: bid around the upper-middle.
        if my_hp <= 2 or no_water_days >= 2:
            target = DAILY_SALARY * 0.8
        else:
            target = max(highest_prev_bid + 5.0, DAILY_SALARY * 0.55)
    else:
        # Low pressure: bid conservatively to preserve budget.
        if my_hp <= 2 or no_water_days >= 2:
            target = DAILY_SALARY * 0.75
        else:
            target = DAILY_SALARY * 0.5

    # Convert target bid into a feasible bid given supply constraints.
    # If supply is tight, we should bid higher to secure water.
    try:
        s = float(supply)
    except Exception:
        s = float(MIN_SUPPLY)

    # Scale with supply tightness: lower supply -> higher bid.
    tightness = (MAX_SUPPLY - s) / float(MAX_SUPPLY - MIN_SUPPLY)
    if tightness < 0.0:
        tightness = 0.0
    if tightness > 1.0:
        tightness = 1.0

    scaled = target * (0.85 + 0.3 * tightness)

    # Also cap based on how many WATER_REQ units we can reasonably want.
    # Ensure bid doesn't exceed budget.
    bid = min(my_budget, scaled)

    # Hard lower/upper bounds for stability
    min_bid = 1.0
    max_bid = my_budget
    if bid < min_bid:
        bid = min_bid
    if bid > max_bid:
        bid = max_bid

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(budget, DAILY_SALARY * 0.2)
    # Base bid: fraction of salary
    if hp <= 2:
        bid = DAILY_SALARY * 0.55
    elif hp <= 4:
        bid = DAILY_SALARY * 0.40
    else:
        bid = DAILY_SALARY * 0.30
    # Adjust for supply: if supply is high, can bid less
    if supply > 20:
        bid *= 0.8
    # Ensure within budget and not too high
    bid = min(budget, bid)
    # Avoid bidding zero if possible
    if bid < 1:
        bid = 1
    return float(bid)
